; ============================================
; evaluate_bayesian_trust (compact loop)
; ============================================
; RCX = likelihoods_trust, RDX = likelihoods_comp
; R8D = n, XMM3 = prior_trust
; Returns: XMM0 = posterior trust
evaluate_bayesian_trust PROC
    mov rax, 3FF0000000000000h
    movq xmm4, rax
    movsd xmm5, xmm4
    subsd xmm5, xmm3
    xor r9d, r9d
bayes_loop:
    cmp r9d, r8d
    jge bayes_done
    movsxd rax, r9d
    movsd xmm1, qword ptr [rcx + rax*8]
    mulsd xmm3, xmm1
    movsd xmm2, qword ptr [rdx + rax*8]
    mulsd xmm5, xmm2
    inc r9d
    jmp bayes_loop
bayes_done:
    movsd xmm0, xmm3
    addsd xmm0, xmm5
    divsd xmm3, xmm0
    movsd xmm0, xmm3
    ret
evaluate_bayesian_trust ENDP

; ============================================
; Master Dispatcher: initialize_wave_field
; Calls 200 unrolled wave seeders
; ============================================
; RCX = phi, EDX = grid_size, XMM2 = d_initial
; XMM3 = amplitude, [rbp+48]=sigma, [rbp+56]=center
initialize_wave_field PROC
    push rbp
    mov rbp, rsp
    push rbx
    push r12
    sub rsp, 64
    ;
    mov rbx, rcx
    mov r12d, edx
    ;
    ; factor = amplitude * (1.0 - d_initial)
    mov rax, 3FF0000000000000h
    movq xmm4, rax
    subsd xmm4, xmm2
    mulsd xmm4, xmm3
    movq qword ptr [rsp], xmm4
    ;
    ; inv_denom = -1.0 / (2.0 * sigma * sigma)
    movsd xmm4, qword ptr [rbp + 48]
    mulsd xmm4, xmm4
    mov rax, 4000000000000000h
    movq xmm5, rax
    mulsd xmm4, xmm5
    mov rax, 3FF0000000000000h
    movq xmm5, rax
    divsd xmm5, xmm4
    mov rax, 8000000000000000h
    movq xmm4, rax
    xorpd xmm5, xmm4
    movq qword ptr [rsp + 8], xmm5
    ;
    ; center
    movsd xmm4, qword ptr [rbp + 56]
    movq qword ptr [rsp + 16], xmm4

    cmp r12d, 0
    jle wave_done
    mov rcx, rbx
    movsd xmm0, qword ptr [rsp]
    movsd xmm1, qword ptr [rsp + 8]
    movsd xmm2, qword ptr [rsp + 16]
    call seed_cell_0000
    cmp r12d, 1
    jle wave_done
    mov rcx, rbx
    movsd xmm0, qword ptr [rsp]
    movsd xmm1, qword ptr [rsp + 8]
    movsd xmm2, qword ptr [rsp + 16]
    call seed_cell_0001
    cmp r12d, 2
    jle wave_done
    mov rcx, rbx
    movsd xmm0, qword ptr [rsp]
    movsd xmm1, qword ptr [rsp + 8]
    movsd xmm2, qword ptr [rsp + 16]
    call seed_cell_0002
    cmp r12d, 3
